-- Weight to billing (O28 of #290, C32 of #291): product's unit gains
-- `tonne`, the outbox the weight review's `weight-reviewed` about an
-- `unload`, and billable_event the `weight` kind naming the Unload whose
-- reviewed net it charges a stop's share of, with that share in kilograms
-- and the consumer's `weight-revised` cancel reason. The consumer's
-- source-event key leaves the weight kind to a key of its own, one row per
-- outbox event and stop, since one review charges every stop its Unload
-- carried. Nothing present changes meaning: no product, event or outbox row
-- holds a new value yet, every billable event passes the respelled kind
-- shape and the new weight shape with both columns null, and the source-event
-- key is rebuilt over the same rows. Nothing is hand-written.
ALTER TABLE "wms"."product" DROP CONSTRAINT "product_unit_one_of";--> statement-breakpoint
ALTER TABLE "wms"."outbox_event" DROP CONSTRAINT "outbox_event_kind_one_of";--> statement-breakpoint
ALTER TABLE "wms"."billable_event" DROP CONSTRAINT "billable_event_kind_one_of";--> statement-breakpoint
ALTER TABLE "wms"."billable_event" DROP CONSTRAINT "billable_event_cancel_reason_one_of";--> statement-breakpoint
ALTER TABLE "wms"."billable_event" DROP CONSTRAINT "billable_event_kind_shape";--> statement-breakpoint
DROP INDEX "wms"."billable_event_source_event_id_idx";--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD COLUMN "unload_id" uuid;--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD COLUMN "weight_kg" integer;--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_unload_id_fk" FOREIGN KEY ("company_id","project_id","unload_id") REFERENCES "wms"."unload"("company_id","project_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "billable_event_weight_charge_idx" ON "wms"."billable_event" USING btree ("company_id","source_event_id","pickup_id") WHERE "wms"."billable_event"."kind" = 'weight';--> statement-breakpoint
CREATE INDEX "billable_event_unload_id_idx" ON "wms"."billable_event" USING btree ("company_id","unload_id");--> statement-breakpoint
CREATE UNIQUE INDEX "billable_event_source_event_id_idx" ON "wms"."billable_event" USING btree ("company_id","source_event_id","kind") WHERE "wms"."billable_event"."source_event_id" is not null and "wms"."billable_event"."kind" not in ('reversal', 'weight');--> statement-breakpoint
ALTER TABLE "wms"."product" ADD CONSTRAINT "product_unit_one_of" CHECK ("wms"."product"."unit" in ('pickup', 'month', 'job', 'day', 'visit', 'item', 'tonne'));--> statement-breakpoint
ALTER TABLE "wms"."outbox_event" ADD CONSTRAINT "outbox_event_kind_one_of" CHECK ("wms"."outbox_event"."kind" in ('route-dispatched', 'route-started', 'route-completed', 'route-cancelled', 'route-reassigned', 'pickup-completed', 'pickup-failed', 'pickup-skipped', 'pickup-problem-reported', 'pickup-corrected', 'unload-recorded', 'command-rejected', 'ticket-opened', 'ticket-completed', 'ticket-rejected', 'invoice-issued', 'settlement-closed', 'application-decided', 'site-visit-recorded', 'site-visit-voided', 'weight-reviewed'));--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_weight_kg_positive" CHECK ("wms"."billable_event"."weight_kg" > 0);--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_weight_shape" CHECK (("wms"."billable_event"."kind" = 'weight') = ("wms"."billable_event"."unload_id" is not null) and ("wms"."billable_event"."unload_id" is null) = ("wms"."billable_event"."weight_kg" is null));--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_kind_one_of" CHECK ("wms"."billable_event"."kind" in ('pickup', 'ticket', 'manual', 'reversal', 'subscription', 'job', 'hire', 'pickup-exception', 'visit', 'weight'));--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_cancel_reason_one_of" CHECK ("wms"."billable_event"."cancel_reason" in ('pickup-corrected', 'visit-voided', 'weight-revised', 'duplicate', 'not-delivered', 'other'));--> statement-breakpoint
ALTER TABLE "wms"."billable_event" ADD CONSTRAINT "billable_event_kind_shape" CHECK (case "wms"."billable_event"."kind" when 'pickup' then "wms"."billable_event"."pickup_id" is not null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'ticket' then "wms"."billable_event"."ticket_id" is not null and "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'manual' then "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null and "wms"."billable_event"."created_by" is not null when 'reversal' then "wms"."billable_event"."reverses_event_id" is not null and "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."net_minor" is not null and "wms"."billable_event"."net_minor" <= 0 when 'subscription' then "wms"."billable_event"."subscription_id" is not null and "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'job' then "wms"."billable_event"."pickup_id" is not null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'hire' then "wms"."billable_event"."subscription_id" is not null and "wms"."billable_event"."placement_id" is not null and "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'pickup-exception' then "wms"."billable_event"."pickup_id" is not null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'visit' then "wms"."billable_event"."visit_id" is not null and "wms"."billable_event"."pickup_id" is null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null when 'weight' then "wms"."billable_event"."unload_id" is not null and "wms"."billable_event"."pickup_id" is not null and "wms"."billable_event"."ticket_id" is null and "wms"."billable_event"."reverses_event_id" is null else false end);